import "./MonitoringWidget.css";
import React, { useEffect, useState } from "react";
import api from "../services/api";

const MonitoringWidget = () => {
  const [metrics, setMetrics] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  // Function to fetch user-specific metrics with authentication
  const fetchMetrics = async () => {
    try {
      const token = localStorage.getItem("token");
      if (!token) {
        setError("Unauthorized: Please log in.");
        setLoading(false);
        return;
      }

      const response = await api.get("/api/auth/metrics/", {
        headers: { Authorization: `Token ${token}` },
      });

      console.log("Fetched Metrics Data:", response.data);

      if (Array.isArray(response.data) && response.data.length > 0) {
        setMetrics(response.data);
        setLoading(false);
      } else {
        setError("No metrics available.");
        setLoading(false);
      }
    } catch (err) {
      console.error("Error fetching metrics:", err);
      setError("Failed to fetch metrics. Please check authentication.");
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchMetrics();
    const interval = setInterval(fetchMetrics, 10000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div>
      <h2>Metrics Monitoring</h2>
      {loading ? <p>Loading...</p> : error ? <p>{error}</p> : null}
      <button onClick={fetchMetrics} className="refresh-btn">Refresh</button>
      <div className="metrics-container">
        {metrics.map((metric, index) => (
          <div key={index} className="metric-card">
            <h3>Server: {metric.server_id}</h3>
            <p><strong>CPU Usage:</strong> {metric.cpu_usage}%</p>
            <p><strong>Memory Usage:</strong> {metric.memory_usage}%</p>
            <p><strong>Disk Usage:</strong> {metric.disk_usage}%</p>
            <p><strong>Uptime:</strong> {Math.floor(metric.uptime / 3600)} hrs</p>
            <p><strong>Timestamp:</strong> {new Date(metric.timestamp).toLocaleString()}</p>
            
            {/* ✅ Ensure status values are always extracted properly */}
            <p>
              <strong>Web Service:</strong> 
              <span className={metric.web_service_status?.status === "Running" ? "status-green" : "status-red"}>
                {metric.web_service_status?.status || "Unknown"}
              </span>
            </p>
            <p>
              <strong>Database Service:</strong> 
              <span className={metric.db_service_status?.status === "Running" ? "status-green" : "status-red"}>
                {metric.db_service_status?.status || "Unknown"}
              </span>
            </p>
          </div>
        ))}
      </div>
    </div>
  );
};

export default MonitoringWidget;
